BEGIN;DO $$DECLARE p record;r record;BEGIN FOR p IN SELECT oid,proowner FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('get_original_refund_sale_v1','get_bound_field_custody_v1') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.oid::regprocedure);FOR r IN SELECT DISTINCT pg_get_userbyid(a.grantee) name FROM pg_proc f CROSS JOIN LATERAL aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a WHERE f.oid=p.oid AND a.grantee<>0 AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',p.oid::regprocedure,r.name);END LOOP;END LOOP;END$$;COMMIT;
